function report=verify_gradient_stress_thermomechanical_control_contract()
%VERIFY_GRADIENT_STRESS_THERMOMECHANICAL_CONTROL_CONTRACT
% Recover a stress generated by the true joint thermo-mechanical forward
% step from the same committed predecessor.  This is a solver contract,
% not a production protocol or an observation fit.
root=fileparts(fileparts(mfilename('fullpath'))); addpath(fullfile(root, 'matlab'));
p=sma.params('niti_zhang2022'); n=3;
old_phase=cell(n,1); old_plastic=cell(n,1);
for i=1:n
    old_phase{i}=struct('xi_A',1,'xi_R',0,'xi_M',0,'xi_MA',0,'xi_MR',0, ...
        'eps_RT',0,'eps_MT',0);
    old_plastic{i}=initial_plastic();
end
weights=ones(n,1)/n;
closure=struct('weights',weights,'dx',1/n,'kappa_MPa_length2',0, ...
    'resistance_shift_MPa',zeros(n,1),'xi_recent',zeros(n,1), ...
    'f_transformable',ones(n,1),'direction_R',ones(n,1), ...
    'direction_M',ones(n,1),'Y_R_MPa',p.R_dissipation,'Tref_K',301, ...
    'phase_residual_tolerance',2e-8,'phase_solver_mode','newton_q', ...
    'stress_control_tolerance_MPa',2e-7,'homogeneous_thermal_reduction',false, ...
    'stress_control_require_single_signature',true);
zc=plastic_closure();
tc=struct('gauge_length_m',0.038,'axial_conductivity_W_mK',18, ...
    'surface_heat_loss_rate_WkgK',p.heat_loss_rate, ...
    'ambient_temperature_K',p.Tamb,'joint_temperature_tolerance_K',1e-7, ...
    'temperature_lower_bound_K',40,'temperature_upper_bound_K',40, ...
    'joint_solver_mode','secant_then_lsq','temperature_scale_K',2.0);
Told=p.Tamb*ones(n,1); dt=1;
[ref_phase,ref_plastic,ref_T,ref]= ...
    sma.candidate_gradient_monolithic_joint_thermomechanical_step_1d( ...
    p,old_phase,old_plastic,Told,0,0.04,dt,closure,zc,tc,struct());
[trial_phase,trial_plastic,trial_T,audit]= ...
    sma.candidate_gradient_monolithic_stress_thermomechanical_step_1d( ...
    p,old_phase,old_plastic,Told,0,ref.stress_MPa,dt,closure,zc,tc,0,struct());
state_error=max([cellfun(@(a,b)abs(a.xi_M-b.xi_M),ref_phase,trial_phase); ...
    cellfun(@(a,b)abs(a.eps_MT-b.eps_MT),ref_phase,trial_phase); ...
    cellfun(@(a,b)abs(a.eps_p_AR-b.eps_p_AR),ref_plastic,trial_plastic)]);
thermal_error=max(abs(ref_T-trial_T));
receipt_bound=isfield(audit.full.mechanical.phase.terms,'source_receipt_required') && ...
    audit.full.mechanical.phase.terms.source_receipt_required;
signature_present=isfield(audit,'signature') && isfield(audit.signature,'key') && ...
    ~strcmp(audit.signature.key,'INVALID');
tc_bad=tc; tc_bad.temperature_lower_bound_K=1e-6; tc_bad.temperature_upper_bound_K=1e-6;
invalid_probe_fail_closed=false; invalid_probe_identifier='';
warning_state=warning; warning('off','all'); warning_cleanup=onCleanup(@()warning(warning_state)); %#ok<NASGU>
try
    sma.candidate_gradient_monolithic_stress_thermomechanical_step_1d( ...
        p,old_phase,old_plastic,Told,0,ref.stress_MPa,dt,closure,zc,tc_bad,0,struct());
catch exception
    invalid_probe_identifier=exception.identifier;
    invalid_probe_fail_closed=strcmp(exception.identifier, ...
        'sma:candidate_gradient_monolithic_stress_thermomechanical_step_1d:Bracket');
end
report=struct('target_stress_MPa',ref.stress_MPa, ...
    'stress_control_residual_MPa',audit.stress_control_residual_MPa, ...
    'thermal_residual_K',audit.full.max_temperature_residual_K, ...
    'state_error',state_error,'thermal_state_error_K',thermal_error, ...
    'receipt_bound',receipt_bound,'signature_present',signature_present, ...
    'invalid_probe_fail_closed',invalid_probe_fail_closed, ...
    'invalid_probe_identifier',invalid_probe_identifier, ...
    'observation_accessed',audit.observation_accessed, ...
    'production_connected',audit.production_connected, ...
    'all_pass',abs(audit.stress_control_residual_MPa)<=2e-7 && ...
    audit.full.max_temperature_residual_K<=1e-7 && state_error<=2e-8 && ...
    thermal_error<=2e-8 && receipt_bound && signature_present && ...
    invalid_probe_fail_closed && ~audit.observation_accessed && ...
    ~audit.production_connected);
assert(report.all_pass,'Gradient thermo-mechanical stress-control contract failed.');
fprintf('GRADIENT_STRESS_THERMO all_pass=%d residual=%.6g thermal=%.6g state_error=%.6g\n', ...
    report.all_pass,report.stress_control_residual_MPa, ...
    report.thermal_residual_K,report.state_error);
end

function s=initial_plastic()
s=struct('xi_M',0,'xi_M_acc',0,'gamma_AR',0,'gamma_M',0, ...
    'eps_p_AR',0,'eps_p_M',0,'rho_AR',0,'rho_M',0,'eps_ARP',0, ...
    'eps_TRIP',0,'chi',0,'beta',0,'xi_Mr',0,'Omega',0,'Yp',0, ...
    'DeltaEtaP_MPaK',0,'Lambda_M',0);
end

function z=plastic_closure()
z=struct('chi_mu0',0.1,'tau0_MPa',200,'Hp_MPa',150e3,'mp',200, ...
    'chi_f0_MPa',550,'chi_p_sat_MPa',200,'b',0.2,'k1_per_m',2e9, ...
    'k2',50,'direction_MT',1,'allow_arp',1,'allow_trip',1, ...
    'max_local_slip_increment',0.1);
end
